#!/usr/bin/env bash
# PullCraft update: applies the "blueprints + push.sh + launch tooling" changes to your existing repo.
# Self-contained: the new/changed files are embedded at the bottom of this script.
#
#   cd ~/path/to/your/pullcraft       # your existing clone
#   bash apply-update.sh              # apply, commit, push
#   bash apply-update.sh --no-push    # apply only, review with `git status` / `git diff`
#   bash apply-update.sh -m "message" # custom commit message
#   bash apply-update.sh --force      # apply even if you have uncommitted changes
#
# It overwrites the files it ships (everything is in git, so you can always undo with
# `git checkout .`). Your own plots/ files and anything it doesn't ship are left alone.
set -euo pipefail

PUSH=1; FORCE=0; MSG="Add CSS/XML blueprints, push.sh and launch tooling"
while [[ $# -gt 0 ]]; do
  case "$1" in
    --no-push) PUSH=0; shift ;;
    --force)   FORCE=1; shift ;;
    -m|--message) MSG="${2:?-m needs a message}"; shift 2 ;;
    -h|--help) sed -n '2,13p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
    *) echo "Unknown option: $1 (try --help)" >&2; exit 1 ;;
  esac
done

say() { printf '\033[1;33m==>\033[0m %s\n' "$*"; }
die() { printf '\033[1;31mError:\033[0m %s\n' "$*" >&2; exit 1; }

command -v git >/dev/null || die "git is not installed."
command -v tar >/dev/null || die "tar is not installed."
[[ -f config.json && -d web && -d scripts ]] || die "Run this from the root of your PullCraft repo (the folder containing config.json, web/ and scripts/)."
git rev-parse --is-inside-work-tree >/dev/null 2>&1 || die "This folder is not a git repository."

if [[ $FORCE -eq 0 ]] && [[ -n "$(git status --porcelain)" ]]; then
  die "You have uncommitted changes. Commit or stash them first, or re-run with --force."
fi

TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
sed '1,/^__PAYLOAD__$/d' "$0" > "$TMP/payload.b64"
if ! base64 --decode < "$TMP/payload.b64" > "$TMP/update.tgz" 2>/dev/null; then
  base64 -D < "$TMP/payload.b64" > "$TMP/update.tgz" || die "Could not decode the embedded update (is the script file complete?)."
fi
tar tzf "$TMP/update.tgz" >/dev/null || die "The embedded update is corrupted. Re-download this script."

say "Applying update"
tar xzf "$TMP/update.tgz" --no-same-owner
chmod +x push.sh scripts/launch-setup.sh 2>/dev/null || true

say "Changed files:"
git status --short | sed 's/^/    /'

if [[ $PUSH -eq 0 ]]; then
  say "Done. Review with 'git diff', then publish with: ./push.sh \"$MSG\""
  exit 0
fi

git add -A
if git diff --cached --quiet; then say "Nothing changed (already up to date)."; fi
exec ./push.sh "$MSG"
exit 0
